import{_ as l,a0 as t,w as d,s as r,ao as o,I as p,x as a,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const q=JSON.parse('{"title":"使用 Linux seq 命令生成數字序列 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Linux seq 命令生成數字序列 | LCTT (202001) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Linux seq 命令生成數字序列 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Linux seq 命令生成數字序列 | LCTT (202001) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202001/20200107 Generating numeric sequences with the Linux seq command","title":"使用 Linux seq 命令生成數字序列","tag":"202001","desc":""},"relativePath":"202001/20200107 Generating numeric sequences with the Linux seq command.md","filePath":"[post].md"}'),c={name:"202001/20200107 Generating numeric sequences with the Linux seq command.md"};function h(g,s,u,k,b,m){const n=t("Link");return d(),r("div",null,[s[15]||(s[15]=o(`<h1 id="使用-linux-seq-命令生成數字序列" tabindex="-1">使用 Linux seq 命令生成數字序列 <a class="header-anchor" href="#使用-linux-seq-命令生成數字序列" aria-label="Permalink to “使用 Linux seq 命令生成數字序列”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202001/15/112717drpb9nuwss84xebu.jpg" alt=""></p><blockquote><p>Linux 的 seq 命令可以以閃電般的速度生成數字列表，而且它也易於使用而且靈活。</p></blockquote><p>在 Linux 中生成數字列表的最簡單方法之一是使用 <code>seq</code>（<ruby>系列<rt>sequence</rt></ruby>）命令。其最簡單的形式是，<code>seq</code> 接收一個數字參數，並輸出從 1 到該數字的列表。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ seq 5</span></span>
<span class="line"><span>1</span></span>
<span class="line"><span>2</span></span>
<span class="line"><span>3</span></span>
<span class="line"><span>4</span></span>
<span class="line"><span>5</span></span></code></pre></div><p>除非另有指定，否則 <code>seq</code> 始終以 1 開頭。你可以在最終數字前面插上不同數字開始一個序列。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ seq 3 5</span></span>
<span class="line"><span>3</span></span>
<span class="line"><span>4</span></span>
<span class="line"><span>5</span></span></code></pre></div><h3 id="指定增量" tabindex="-1">指定增量 <a class="header-anchor" href="#指定增量" aria-label="Permalink to “指定增量”">​</a></h3><p>你還可以指定增量步幅。假設你要列出 3 的倍數。指定起點（在此示例中為第一個 3 ），增量（第二個 3）和終點（18）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ seq 3 3 18</span></span>
<span class="line"><span>3</span></span>
<span class="line"><span>6</span></span>
<span class="line"><span>9</span></span>
<span class="line"><span>12</span></span>
<span class="line"><span>15</span></span>
<span class="line"><span>18</span></span></code></pre></div><p>你可以選擇使用負增量（即減量）將數字從大變小。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ seq 18 -3 3</span></span>
<span class="line"><span>18</span></span>
<span class="line"><span>15</span></span>
<span class="line"><span>12</span></span>
<span class="line"><span>9</span></span>
<span class="line"><span>6</span></span>
<span class="line"><span>3</span></span></code></pre></div><p><code>seq</code> 命令也非常快。你或許可以在 10 秒內生成一百萬個數字的列表。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ time seq 1000000</span></span>
<span class="line"><span>1</span></span>
<span class="line"><span>2</span></span>
<span class="line"><span>3</span></span>
<span class="line"><span>…</span></span>
<span class="line"><span>…</span></span>
<span class="line"><span>999998</span></span>
<span class="line"><span>999999</span></span>
<span class="line"><span>1000000</span></span>
<span class="line"><span></span></span>
<span class="line"><span>real    0m9.290s  &lt;== 9+ seconds</span></span>
<span class="line"><span>user    0m0.020s</span></span>
<span class="line"><span>sys     0m0.899s</span></span></code></pre></div><h3 id="使用分隔符" tabindex="-1">使用分隔符 <a class="header-anchor" href="#使用分隔符" aria-label="Permalink to “使用分隔符”">​</a></h3><p>另一個非常有用的選項是使用分隔符。你可以插入逗號、冒號或其他一些字符，而不是在每行上列出單個數字。<code>-s</code> 選項後跟要使用的字符。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ seq -s: 3 3 18</span></span>
<span class="line"><span>3:6:9:12:15:18</span></span></code></pre></div><p>實際上，如果只是希望將數字列在一行上，那麼可以使用空格代替默認的換行符。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ seq -s&#39; &#39;  3 3 18</span></span>
<span class="line"><span>3 6 9 12 15 18</span></span></code></pre></div><h3 id="開始數學運算" tabindex="-1">開始數學運算 <a class="header-anchor" href="#開始數學運算" aria-label="Permalink to “開始數學運算”">​</a></h3><p>從生成數字序列到進行數學運算似乎是一個巨大的飛躍，但是有了正確的分隔符，<code>seq</code> 可以輕鬆地傳遞給 <code>bc</code> 進行計算。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ seq -s* 5 | bc</span></span>
<span class="line"><span>120</span></span></code></pre></div><p>該命令中發生了什麼？讓我們來看看。首先，<code>seq</code> 生成一個數字列表，並使用 <code>*</code> 作為分隔符。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ seq -s* 5</span></span>
<span class="line"><span>1*2*3*4*5</span></span></code></pre></div><p>然後，它將字符串傳遞給計算器（<code>bc</code>），計算器立即將數字相乘。你可以在不到一秒的時間內進行相當龐大的計算。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ time seq -s* 117 | bc</span></span>
<span class="line"><span>39699371608087208954019596294986306477904063601683223011297484643104\\</span></span>
<span class="line"><span>22041758630649341780708631240196854767624444057168110272995649603642\\</span></span>
<span class="line"><span>560353748940315749184568295424000000000000000000000000000</span></span>
<span class="line"><span></span></span>
<span class="line"><span>real    0m0.003s</span></span>
<span class="line"><span>user    0m0.004s</span></span>
<span class="line"><span>sys     0m0.000s</span></span></code></pre></div><h3 id="侷限性" tabindex="-1">侷限性 <a class="header-anchor" href="#侷限性" aria-label="Permalink to “侷限性”">​</a></h3><p>你只能選擇一個分隔符，因此計算將非常有限。而單獨使用 <code>bc</code> 可進行更復雜的數學運算。此外，<code>seq</code> 僅適用於數字。要生成單個字母的序列，請改用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo {a..g}</span></span>
<span class="line"><span>a b c d e f g</span></span></code></pre></div><hr>`,30)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://www.networkworld.com/article/3511954/generating-numeric-sequences-with-the-linux-seq-command.html"},{default:i(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3511954/generating-numeric-sequences-with-the-linux-seq-command.html",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:i(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const y=l(c,[["render",h]]);export{q as __pageData,y as default};
